from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = re.compile(r":?-+:?")


def _cell_text(value: object) -> str:
    """Render one value as escaped cell text."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    """Pad text to width according to an alignment."""
    extra = width - len(text)
    if align == "right":
        return " " * extra + text
    if align == "center":
        left = extra // 2
        return " " * left + text + " " * (extra - left)
    return text + " " * extra


def _delimiter(width: int, align: str | None) -> str:
    """Build one delimiter cell of the given width."""
    cell = "-" * width
    if align in ("left", "center"):
        cell = ":" + cell[1:]
    if align in ("right", "center"):
        cell = cell[:-1] + ":"
    return cell


def _format_line(
    cells: list[str], widths: list[int], alignments: list[str | None]
) -> str:
    padded = [
        _pad(cell, width, alignment)
        for cell, width, alignment in zip(cells, widths, alignments)
    ]
    return "| " + " | ".join(padded) + " |"


def _is_escaped(text: str, index: int) -> bool:
    """Whether the character at index is preceded by a backslash."""
    return index > 0 and text[index - 1] == "\\"


def _split_cells(line: str) -> list[str]:
    """Split one table line into stripped, unescaped cells."""
    text = line.strip()
    if text.startswith("|"):
        text = text[1:]
    if text.endswith("|") and not _is_escaped(text, len(text) - 1):
        text = text[:-1]

    cells = []
    current = []
    index = 0
    while index < len(text):
        char = text[index]
        if char == "\\" and index + 1 < len(text) and text[index + 1] == "|":
            current.append("|")
            index += 2
        elif char == "|":
            cells.append("".join(current).strip())
            current = []
            index += 1
        else:
            current.append(char)
            index += 1
    cells.append("".join(current).strip())
    return cells


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    header = list(header)
    if not header:
        raise ValueError("header must have at least one column")

    if align is None:
        alignments = [None] * len(header)
    else:
        alignments = list(align)
        if len(alignments) != len(header):
            raise ValueError("align must have one entry per column")
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    header_cells = [_cell_text(value) for value in header]

    body = []
    for row in rows:
        row_cells = [_cell_text(value) for value in row]
        if len(row_cells) > len(header_cells):
            raise ValueError("row has more cells than the header")
        row_cells.extend([""] * (len(header_cells) - len(row_cells)))
        body.append(row_cells)

    widths = []
    for index, cell in enumerate(header_cells):
        width = max(3, len(cell))
        for row_cells in body:
            width = max(width, len(row_cells[index]))
        widths.append(width)

    lines = [_format_line(header_cells, widths, alignments)]
    delimiter_cells = [
        _delimiter(width, alignment)
        for width, alignment in zip(widths, alignments)
    ]
    lines.append(_format_line(delimiter_cells, widths, [None] * len(widths)))
    lines.extend(_format_line(row_cells, widths, alignments) for row_cells in body)
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    if len(lines) < 2:
        raise ValueError("a table needs a header and a delimiter line")
    if lines[0].strip() == "":
        raise ValueError("header line is empty")

    header = _split_cells(lines[0])
    delimiter_cells = _split_cells(lines[1])
    if len(delimiter_cells) != len(header):
        raise ValueError("delimiter line has a different number of cells than the header")

    alignments = []
    for cell in delimiter_cells:
        if _DELIMITER_RE.fullmatch(cell) is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        if cell.startswith(":") and cell.endswith(":"):
            alignments.append("center")
        elif cell.startswith(":"):
            alignments.append("left")
        elif cell.endswith(":"):
            alignments.append("right")
        else:
            alignments.append(None)

    rows = []
    for line in lines[2:]:
        if line.strip() == "":
            raise ValueError("blank line in table body")
        row = _split_cells(line)
        if len(row) != len(header):
            raise ValueError("row has a different number of cells than the header")
        rows.append(row)

    return header, rows, alignments
